CREATE OR REPLACE FUNCTION public.mha_admin_user_matrix_catalog()\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nbegin\n if auth.uid() is null or not exists(select 1 from public.mha_super_admin_identity sa join public.mha_user_profile u on u.user_id=sa.user_id where sa.user_id=auth.uid() and u.is_active and u.is_super_admin) then raise exception 'Super Admin access required' using errcode='42501';end if;\n return jsonb_build_object(\n 'companies',coalesce((select jsonb_agg(jsonb_build_object('id',id,'company_name',company_name,'is_active',is_active) order by company_name) from public.mha_company),'[]'::jsonb),\n 'roles',coalesce((select jsonb_agg(jsonb_build_object('id',id,'company_id',company_id,'role_code',role_code,'role_name',role_name,'is_active',is_active) order by company_id,role_code) from public.mha_role),'[]'::jsonb),\n 'permissions',coalesce((select jsonb_agg(jsonb_build_object('role_id',role_id,'submodule_code',submodule_code,'access_level',access_level)) from public.mha_role_permission),'[]'::jsonb)\n );\nend $function$\n

-- Explicit least-privilege grants are required on a fresh migration replay.
REVOKE ALL ON FUNCTION public.mha_admin_user_matrix_catalog() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mha_admin_user_matrix_catalog() TO authenticated;
